with x as (select * from json_to_recordset('[{"s":"rafiki","t":"Rafiki | Boiler Room x Ballantine''s True Music Studios Mumbai: Krunk Presents","u":"https://soundcloud.com/platform/rafiki-krunk-presents-kiss"}]'::json) as x(s text,t text,u text) where exists (select 1 from public.artists a where a.slug=x.s)), ins as (insert into public.artist_tracklists (artist_slug,mix_title,url,tracks) select x.s,x.t,x.u,'[]'::jsonb from x on conflict (artist_slug,url) do nothing returning 1), fill as (update public.artists a set mix_url=f.u from (select distinct on (x.s) x.s,x.u from x order by x.s, (x.u ~ '(soundcloud\.com|youtube\.com|youtu\.be|mixcloud\.com)') desc) f where a.slug=f.s and a.mix_url is null returning 1) select (select count(*) from ins) ins, (select count(*) from fill) filled;